using System.Net.Http;\nusing System.Text;\nusing System.Text.Json;\nusing System.Threading.Tasks;\nusing Xunit;\n\nnamespace TestProject.Api.Tests\n{\n    public class ApiTests\n    {\n        private readonly HttpClient _client;\n\n        public ApiTests()\n        {\n            _client = new HttpClient { BaseAddress = new Uri(\"https://api.example.com\") };\n        }\n\n        [Fact]\n        public async Task GetItems_ShouldReturnItems()\n        {\n            var response = await _client.GetAsync(\"/api/items\");\n            response.EnsureSuccessStatusCode();\n\n            var responseString = await response.Content.ReadAsStringAsync();\n            Assert.False(string.IsNullOrWhiteSpace(responseString));\n        }\n\n        [Fact]\n        public async Task PostItem_ShouldCreateNewItem()\n        {\n            var newItem = new { Name = \"Test Item\", Description = \"This is a test item\" };\n            var content = new StringContent(JsonSerializer.Serialize(newItem), Encoding.UTF8, \"application/json\");\n\n            var response = await _client.PostAsync(\"/api/items\", content);\n            response.EnsureSuccessStatusCode();\n\n            var responseString = await response.Content.ReadAsStringAsync();\n            Assert.False(string.IsNullOrWhiteSpace(responseString));\n        }\n    }\n}\n